import{_ as s,C as n,o as t,c as d,a2 as a,b as h,w as o,a as i,E as l,a3 as c}from"./chunks/framework.2af478d7.js";const k=JSON.parse('{"title":"Caching model","description":"","frontmatter":{},"headers":[],"relativePath":"caching-model.md","filePath":"caching-model.md"}'),u={name:"caching-model.md"};function p(f,e,g,m,b,w){const r=n("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="caching-model" tabindex="-1">Caching model <a class="header-anchor" href="#caching-model" aria-label="Permalink to &quot;Caching model&quot;">​</a></h1><p>The package caches Drupal&#39;s JSON:API documents in Laravel&#39;s cache. Entries stay fresh for minutes, stay available for a day, and a single counter, the <a href="./vocabulary#content-generation">content generation</a>, invalidates all of them at once.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Choose a <a href="./installation#choose-a-cache-store">cache store</a>. Know the <a href="./vocabulary#fresh-and-stale-window">fresh and stale window</a> and the <a href="./vocabulary#negative-cache">negative cache</a> terms.</p><h2 id="how-a-lookup-works" tabindex="-1">How a lookup works <a class="header-anchor" href="#how-a-lookup-works" aria-label="Permalink to &quot;How a lookup works&quot;">​</a></h2><p>Every read goes through <code>CachedDrupal</code>. The diagram shows one lookup, from the check for an unknown alias to the stored entry.</p>',6)),(t(),h(c,null,{default:o(()=>[l(r,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TD%0A%20%20Request%5B%22Cache%20read%22%5D%20--%3E%20Remembered%7B%22Alias%20remembered%20as%20unknown%3F%22%7D%0A%20%20Remembered%20--%3E%7Cyes%7C%20NotFound%5B%22DrupalNotFound%22%5D%0A%20%20Remembered%20--%3E%7Cno%7C%20Entry%7B%22Entry%20exists%3F%22%7D%0A%20%20Entry%20--%3E%7Cno%7C%20Client%5B%22DrupalClient%22%5D%0A%20%20Entry%20--%3E%7Cyes%7C%20Fresh%7B%22Entry%20fresh%3F%22%7D%0A%20%20Fresh%20--%3E%7Cyes%7C%20Serve%5B%22Serve%20the%20entry%22%5D%0A%20%20Fresh%20--%3E%7Cno%7C%20Refresh%5B%22Serve%20the%20stale%20entry%2C%20refresh%20after%20the%20response%22%5D%0A%20%20Refresh%20--%3E%20Client%0A%20%20Client%20--%3E%7Canswer%7C%20Store%5B%22Store%20the%20entry%22%5D%0A%20%20Store%20--%3E%20Serve%0A%20%20Client%20--%3E%7Cunknown%20alias%7C%20Remember%5B%22Remember%20the%20alias%20as%20unknown%22%5D%0A%20%20Remember%20--%3E%20NotFound%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ul><li><strong>Fresh hit.</strong> The entry is younger than <code>drupal.cache.fresh</code>. It is served without a call to Drupal.</li><li><strong>Stale hit.</strong> The entry is older than the fresh window but younger than <code>fresh + stale</code>. Your visitor gets the stale copy immediately, and Laravel refreshes it after the response is sent. If the refresh fails, the stale copy stays.</li><li><strong>Miss.</strong> No entry exists. The request waits for Drupal. If Drupal fails, the visitor sees the <a href="./vocabulary#failures">failure outcome</a>, because there is nothing stale to serve.</li><li><strong>Unknown alias.</strong> Drupal answered 404 for an alias, so the package remembers it for <code>drupal.cache.negative</code> seconds. Repeated requests for that URL skip Drupal.</li></ul><p>The &quot;alias remembered&quot; check applies only to alias resolution; item and collection reads start at &quot;Entry exists?&quot;.</p><h2 id="what-is-cached" tabindex="-1">What is cached <a class="header-anchor" href="#what-is-cached" aria-label="Permalink to &quot;What is cached&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Window</th><th>Notes</th></tr></thead><tbody><tr><td>Items and listing pages</td><td>Fresh, then stale</td><td>Stale-while-revalidate, also serves stale when Drupal fails.</td></tr><tr><td>Alias resolution</td><td>Fresh, then stale</td><td>Stores the Drupal resource that an alias points to.</td></tr><tr><td>Unknown alias</td><td><code>drupal.cache.negative</code></td><td>Only an answer of not found is remembered.</td></tr><tr><td>Search results</td><td><code>search.cache</code> seconds, fresh only</td><td>No stale copy, no serving stale on errors. <code>0</code> disables it.</td></tr><tr><td>Search suggestions</td><td>Not cached</td><td>They always ask Drupal.</td></tr></tbody></table><p>The package never caches an unavailable or bad response, and it does not remember an alias that resolved to a different content type.</p><h2 id="the-content-generation" tabindex="-1">The content generation <a class="header-anchor" href="#the-content-generation" aria-label="Permalink to &quot;The content generation&quot;">​</a></h2><p>Every cache key has the form <code>drupal:{source}:{generation}:{hash}</code>. The hash covers the request: resource, query, limit and offset for a collection, or resource, UUID and query for an item.</p><p>Each Source has its own generation, a UUID stored without an expiry under <code>drupal:generation:{source}</code>. Replacing the UUID changes every key of that Source, so old entries stop being found. The package deletes nothing; old entries expire on their own after the stale window. This needs no tags, so it works on every cache store.</p><p>You replace a generation in two ways:</p><ul><li>The signed <a href="./webhook-and-cache-flushing">webhook</a> from Drupal, whenever content changes.</li><li><code>php artisan drupal:flush</code>, which flushes every Source, or <code>php artisan drupal:flush reviews</code> for one.</li></ul><p>A Source can list other Sources under <code>flush.also.sources</code>. Flushing it flushes those too. See <a href="./multiple-drupal-sources">Multiple Drupal sources</a>.</p><p>Until you set up the webhook, content updates reach visitors when the fresh window ends, at most <code>drupal.cache.fresh</code> seconds after the change.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>drupal.cache.enabled</code></td><td>bool</td><td><code>true</code></td><td><code>false</code> skips every layer, including search. Use it in local development.</td></tr><tr><td><code>drupal.cache.fresh</code></td><td>int</td><td><code>300</code></td><td>Seconds an entry is served without revalidation.</td></tr><tr><td><code>drupal.cache.stale</code></td><td>int</td><td><code>86400</code></td><td>Seconds past the fresh window that a stale copy is still served.</td></tr><tr><td><code>drupal.cache.negative</code></td><td>int</td><td><code>60</code></td><td>Seconds an unknown alias is remembered.</td></tr><tr><td><code>drupal.cache.store</code></td><td>?string</td><td><code>null</code></td><td>Cache store for package entries. <code>null</code> uses the default store.</td></tr><tr><td><code>search.cache</code></td><td>int</td><td><code>60</code></td><td>Seconds a search result is served without refetching. Set in the descriptor.</td></tr></tbody></table><p>The environment variables behind these keys are listed under <a href="./installation#environment-variables">Installation</a>.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>The webhook remembers each accepted signature in the default cache store, even when <code>drupal.cache.store</code> names another one.</li><li>Entries are plain JSON:API arrays, not models, so renaming a field or changing your <code>Entity</code> subclass needs no flush.</li><li>Changing the <code>includes</code> of a content type changes the request and so the hash. The package never reads the old entries again.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Connect Drupal with <a href="./webhook-and-cache-flushing">Webhook and cache flushing</a>.</li><li>See where the cache sits in the <a href="./architecture">Architecture</a>.</li><li>Diagnose stale content in <a href="./troubleshooting">Troubleshooting</a>.</li></ul>',19))])}const v=s(u,[["render",p]]);export{k as __pageData,v as default};
